  expect(() => advanceFen1(w)).toThrow();
});

test("advanceFen1: succeeds once Osk is 'pex'", () => {
  let w = createInitialWorld();
  w = advanceOsk1(w); // osk: pex
  const w2 = advanceFen1(w);
  expect(w2.fen).toBe("pex");
});

// --- advanceFen2 tests ---

test("advanceFen2: fails if Zef is not 'pex'", () => {
  // Fen=pex, Osk=pex だが Zef=nim のままなので失敗する
  let w = createInitialWorld();
  w = advanceOsk1(w);  // osk: pex
  w = advanceFen1(w);  // fen: pex
  expect(() => advanceFen2(w)).toThrow(); // zef still nim
});

test("advanceFen2: succeeds once Osk is 'pex' and Zef is 'pex'", () => {
  // advanceFen2 requires Fen=pex, Osk=pex, Zef=pex
  // (D7: O8 depends on E5, D8: O8 depends on E2)
  let w = createInitialWorld();
  w = advanceTal1(w);   // tal: pex (advanceZef1の前提)
  w = advanceZef1(w);   // zef: pex
  w = advanceOsk1(w);   // osk: pex
  w = advanceFen1(w);   // fen: pex (osk=pexなので成功)
  const w2 = advanceFen2(w);
  expect(w2.fen).toBe("dor");
});

// --- resetFen tests ---

test("resetFen: pex -> nim succeeds", () => {
  let w = createInitialWorld();
  w = advanceOsk1(w);   // osk: pex (advanceFen1の前提)
