  expect(w.fen).toBe("pex");
  w = resetFen(w);      // fen: nim (rollback)
  expect(w.fen).toBe("nim");
  // Can re-advance after rollback
  w = advanceFen1(w);   // fen: pex again
  expect(w.fen).toBe("pex");
});
